SELECT toString(properties.surface) AS Surface,uniqExactIf(properties.recording_id,event='studio_recording_started') AS Started,uniqExactIf(properties.recording_id,event='studio_recording_completed') AS Completed,uniqExactIf(properties.recording_id,event='studio_recording_failed') AS Failed FROM events WHERE event IN ('studio_recording_started','studio_recording_completed','studio_recording_failed') AND properties.environment = 'production' AND properties.product = 'studio' AND {filters} GROUP BY Surface LIMIT 10
